import os,re,json
AJC="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge"
AJCR="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"
LED=AJC+"/AlgebraicJacobian/RiemannRoch/Ledger"
ported={f[:-5] for f in os.listdir(LED) if f.endswith('.lean')}
ajc_native=set()
for root,d,fs in os.walk(AJC+"/AlgebraicJacobian"):
    if '/Ledger' in root: continue
    for f in fs:
        if f.endswith('.lean'):
            ajc_native.add(os.path.relpath(os.path.join(root,f),AJC)[:-5].replace('/','.'))
imp=re.compile(r'^import\s+(AlgebraicJacobian[A-Za-z0-9_.]*)')
def rd(p):
    return [m.group(1) for m in (imp.match(l) for l in open(p)) if m]
def ajcr_path(mod): return os.path.join(AJCR,mod.replace('.','/')+'.lean')
def lines(p): return sum(1 for _ in open(p))
# hybrid: ported basenames resolve to AJC Ledger file & its imports; else AJCR
def imports(mod):
    b=mod.split('.')[-1]
    if b in ported and os.path.exists(os.path.join(LED,b+'.lean')):
        return rd(os.path.join(LED,b+'.lean')), 'ported'
    if mod in ajc_native:
        return [], 'ajc-native'   # already available, stop
    p=ajcr_path(mod)
    if not os.path.exists(p): return None,'MISSING'
    return rd(p),'extra'
def closure(mod):
    seen={}; stack=[mod]
    while stack:
        m=stack.pop()
        if m in seen: continue
        i,kind=imports(m)
        seen[m]=kind
        if i is None: continue
        stack.extend(i)
    return seen
targets=["UniformVanishing","FLVVanishing","SectionBound","BpfSpan","BpfSpanCore","BaseDivisor","BaseDivisorSpan","DegreeBaseFieldInvariance","CoverageDrop"]
out=[]
for t in targets:
    seen=closure("AlgebraicJacobian.RiemannRoch."+t)
    extra=sorted(m for m,k in seen.items() if k=='extra')
    miss=sorted(m for m,k in seen.items() if k=='MISSING')
    el=sum(lines(ajcr_path(m)) for m in extra)
    tot=0
    for m,k in seen.items():
        if k=='ported': tot+=lines(os.path.join(LED,m.split('.')[-1]+'.lean'))
        elif k=='extra': tot+=lines(ajcr_path(m))
    out.append(dict(t=t,nseen=len(seen),tot=tot,nextra=len(extra),el=el,extra=extra,miss=miss,
        nported=sum(1 for k in seen.values() if k=='ported'),najc=sum(1 for k in seen.values() if k=='ajc-native')))
out.sort(key=lambda r:(r['nextra'],r['el']))
print(f"{'target':28s} {'closure':>7s} {'ported':>6s} {'ajcNat':>6s} {'EXTRA':>5s} {'extraLines':>10s}")
for r in out:
    print(f"{r['t']:28s} {r['nseen']:7d} {r['nported']:6d} {r['najc']:6d} {r['nextra']:5d} {r['el']:10d}")
    if r['miss']: print("   MISSING:",r['miss'])
json.dump(out,open('/tmp/closure2.json','w'),indent=1)
print()
for r in out:
    print(f"=== {r['t']}: {r['nextra']} extra / {r['el']} lines")
    for m in r['extra']: print(f"    {lines(ajcr_path(m)):5d}  {m}")
EOF
